        df = df.copy()
        df['date'] = pd.to_datetime(df['date'])
    except Exception:
        raise ValueError("'df' contains invalid data types.")

    series = df.set_index('date')['value'].sort_index()
    try:
        series = series.asfreq(freq)
    except Exception:
        raise ValueError("'freq' is not a valid frequency string.")

